<script setup lang="ts">import{onMounted,ref}from"vue";import{admApi}from"../../shared/cpfApi";type Row=Record<string,any>;const rows=ref<Row[]>([]),error=ref("");const form=ref({serviceId:"",endpointCode:"",instanceId:"",action:"DRAIN",reason:"정기 점검"});async function api(url:string,opt:RequestInit={}){return admApi(url,opt)}async function load(){try{rows.value=await api('/adm/api/maintenance/actions?limit=100')}catch(e){error.value=e instanceof Error?e.message:String(e)}}async function execute(){try{await api('/adm/api/maintenance/actions',{method:'POST',body:JSON.stringify(form.value)});await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}}onMounted(load);</script><template><div class="cpf-page"><div class="cpf-page-heading"><div><p class="eyebrow">MAINTENANCE / DRAIN</p><h2>점검·Drain 제어</h2><p>서비스 Instance를 안전하게 Drain/Disable/Resume하고 모든 운영 명령을 감사 이력으로 남깁니다.</p></div></div><section class="cpf-card"><div class="cpf-card-head"><h2>운영 명령</h2></div><div class="cpf-form-grid"><label>Service<input v-model="form.serviceId" placeholder="MBR"></label><label>Endpoint<input v-model="form.endpointCode" placeholder="MBR_API"></label><label>Instance<input v-model="form.instanceId" placeholder="MBR-01"></label><label>Action<select v-model="form.action"><option value="DRAIN">DRAIN</option><option value="DISABLE">DISABLE</option><option value="RESUME">RESUME</option></select></label><label class="span-2">감사 사유<input v-model="form.reason"></label><button class="danger" @click="execute">명령 실행</button></div><p class="cpf-note">실행 명령은 Service Registry Control Port를 통해 Owner 경계에서 처리됩니다.</p></section><section class="cpf-card"><div class="cpf-card-head"><h2>최근 점검 명령</h2></div><p v-if="error" class="error-banner">{{error}}</p><div class="table-wrap"><table><thead><tr><th>시간</th><th>Service</th><th>Instance</th><th>Action</th><th>결과</th><th>사유</th></tr></thead><tbody><tr v-for="r in rows" :key="String(r.actionId)"><td>{{r.requestedAt}}</td><td>{{r.serviceId}}</td><td>{{r.instanceId}}</td><td>{{r.actionType}}</td><td>{{r.resultStatus}}</td><td>{{r.reason}}</td></tr></tbody></table></div></section></div></template>